mapper.insert:
INSERT INTO graph_projection_state (
    achievement_id, desired_version, applied_version, last_enqueued_at
) VALUES (
    #{achievementId}, 1, 0, #{now}
)
ON DUPLICATE KEY UPDATE
    desired_version = desired_version + 1,
    last_enqueued_at = VALUES(last_enqueued_at)

mapper.select:
SELECT desired_version
FROM graph_projection_state
WHERE achievement_id = #{achievementId}

mapper.insert:
INSERT INTO graph_outbox_event (
    event_id, achievement_id, desired_version, next_attempt_at
) VALUES (
    #{eventId}, #{achievementId}, #{desiredVersion}, #{now}
)
